import { ENVIRONMENT } from '../../constants/env.js';
import type { EmailTemplateData, RenderedEmail } from '../../types/emailTypes.js';
import { EmailTemplateId } from '../../types/emailTypes.js';
import { sendEmailViaSmtp } from './smtp.js';
import { renderEmailLoginOtpTemplate } from './templates/emailLoginOtpTemplate.js';

export { EmailTemplateId } from '../../types/emailTypes.js';
export type {
	EmailLoginOtpTemplateData,
	EmailRecipient,
	EmailTemplateData,
	RenderedEmail,
} from '../../types/emailTypes.js';

export const renderEmailTemplate = (templateId: EmailTemplateId, templateData: EmailTemplateData): RenderedEmail => {
	switch (templateId) {
		case EmailTemplateId.EmailLoginOtp:
			return renderEmailLoginOtpTemplate(templateData);
	}
};

export const sendEmail = async (templateId: EmailTemplateId, templateData: EmailTemplateData): Promise<void> => {
	const { subject, textBody, htmlBody } = renderEmailTemplate(templateId, templateData);
	if (ENVIRONMENT !== 'testing') {
		await sendEmailViaSmtp({
			to: templateData.to,
			subject,
			textBody,
			htmlBody,
			replyTo: templateData.replyTo,
		});
	}
};
